INSERT INTO ref_banks (bank_code, bank_name, country, is_active) SELECT bank_code, bank_name, country, 1 FROM tmp_cglt527_bank_master ON DUPLICATE KEY UPDATE bank_name = VALUES(bank_name), is_active = 1;
UPDATE m_client_other_info coi INNER JOIN ref_banks old_bank ON old_bank.id = coi.bank_id INNER JOIN ref_banks new_bank ON new_bank.country = 'Rwanda' AND new_bank.bank_code = '44' SET coi.bank_id = new_bank.id, coi.bank_name = NULL WHERE old_bank.country = 'Rwanda' AND old_bank.bank_code = '50';
UPDATE m_client_other_info coi INNER JOIN ref_banks old_bank ON old_bank.id = coi.bank_id LEFT JOIN tmp_cglt527_bank_master master_bank ON master_bank.country = old_bank.country AND master_bank.bank_code = old_bank.bank_code SET coi.bank_name = COALESCE(NULLIF(coi.bank_name, ''), old_bank.bank_name), coi.bank_id = NULL WHERE master_bank.bank_code IS NULL;
DELETE old_bank FROM ref_banks old_bank LEFT JOIN tmp_cglt527_bank_master master_bank ON master_bank.country = old_bank.country AND master_bank.bank_code = old_bank.bank_code WHERE master_bank.bank_code IS NULL;
DROP TEMPORARY TABLE IF EXISTS tmp_cglt527_bank_master;
